-- Uploaded assets, feedback, and waitlist capture.
CREATE TABLE IF NOT EXISTS assets (id SERIAL PRIMARY KEY, filename TEXT NOT NULL, original_filename TEXT NOT NULL, mime_type TEXT NOT NULL, size_bytes BIGINT NOT NULL, storage_path TEXT NOT NULL, thumbnail_path TEXT, alt_text TEXT, category TEXT DEFAULT 'general' CHECK (category IN ('logo','favicon','og_image','general')), uploaded_by TEXT, created_at TIMESTAMP DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_assets_category ON assets(category); CREATE INDEX IF NOT EXISTS idx_assets_created ON assets(created_at);
CREATE TABLE IF NOT EXISTS feedback_requests (id SERIAL PRIMARY KEY, type VARCHAR(50) NOT NULL CHECK (type IN ('refund','bug','feature','general')), email VARCHAR(255) NOT NULL, subject VARCHAR(500) NOT NULL, message TEXT NOT NULL, order_id VARCHAR(255), status VARCHAR(50) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','in_progress','resolved','rejected')), created_at TIMESTAMP DEFAULT NOW(), updated_at TIMESTAMP DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_feedback_requests_type ON feedback_requests(type); CREATE INDEX IF NOT EXISTS idx_feedback_requests_status ON feedback_requests(status); CREATE INDEX IF NOT EXISTS idx_feedback_requests_email ON feedback_requests(email); CREATE INDEX IF NOT EXISTS idx_feedback_requests_created ON feedback_requests(created_at);
CREATE TABLE IF NOT EXISTS waitlist_emails (id SERIAL PRIMARY KEY, email VARCHAR(255) UNIQUE NOT NULL, source VARCHAR(50) DEFAULT 'coming_soon', created_at TIMESTAMP DEFAULT NOW()); CREATE INDEX IF NOT EXISTS idx_waitlist_emails_email ON waitlist_emails(email);
